#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> rs(n + 1), cs(n + 1);
    for (auto &x : rs) cin >> x;
    for (auto &x : cs) cin >> x;
    const long long NONE = LLONG_MAX;
    // dp[x] = minimum cost to cover [0, x]; NONE if impossible.
    vector<long long> dp(n + 1, NONE), baseByLeft(n + 1, NONE);
    dp[0] = 0;
    for (int right = 1; right <= n; right++) {
        // baseByLeft[x] = min dp over [x, right-1]: a sprinkler starting at x can extend any of those prefixes.
        int low = max(0, right - 200);
        long long prefixBest = NONE;
        for (int x = right - 1; x >= low; x--) {
            prefixBest = min(prefixBest, dp[x]);
            baseByLeft[x] = prefixBest;
        }
        long long best = NONE;
        for (int i = max(0, right - 100); i <= min(n, right + 100); i++) {
            long long left = max(0LL, i - rs[i]), far = min((long long)n, i + rs[i]);
            if (far < right || left >= right) continue;
            long long base = baseByLeft[left];
            if (base != NONE) best = min(best, base + cs[i]);
        }
        dp[right] = best;
    }
    cout << (dp[n] == NONE ? -1 : dp[n]) << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] rs = new long[n + 1], cs = new long[n + 1];
        for (int i = 0; i <= n; i++) rs[i] = nextLong();
        for (int i = 0; i <= n; i++) cs[i] = nextLong();
        final long NONE = Long.MAX_VALUE;
        // dp[x] = minimum cost to cover [0, x]; NONE if impossible.
        long[] dp = new long[n + 1], baseByLeft = new long[n + 1];
        Arrays.fill(dp, NONE);
        dp[0] = 0;
        for (int right = 1; right <= n; right++) {
            // baseByLeft[x] = min dp over [x, right-1]: a sprinkler starting at x can extend any of those prefixes.
            int low = Math.max(0, right - 200);
            long prefixBest = NONE;
            for (int x = right - 1; x >= low; x--) {
                prefixBest = Math.min(prefixBest, dp[x]);
                baseByLeft[x] = prefixBest;
            }
            long best = NONE;
            for (int i = Math.max(0, right - 100); i <= Math.min(n, right + 100); i++) {
                long left = Math.max(0, i - rs[i]), far = Math.min(n, i + rs[i]);
                if (far < right || left >= right) continue;
                long base = baseByLeft[(int) left];
                if (base != NONE) best = Math.min(best, base + cs[i]);
            }
            dp[right] = best;
        }
        System.out.println(dp[n] == NONE ? -1 : dp[n]);
    }
}

package main

import (
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	rs := make([]int, n+1)
	cs := make([]int64, n+1)
	for i := range rs {
		rs[i] = int(nextInt())
	}
	for i := range cs {
		cs[i] = nextInt()
	}
	const none = int64(math.MaxInt64)
	// dp[x] = minimum cost to cover [0, x]; none if impossible.
	dp := make([]int64, n+1)
	baseByLeft := make([]int64, n+1)
	for i := range dp {
		dp[i] = none
	}
	dp[0] = 0
	for right := 1; right <= n; right++ {
		// baseByLeft[x] = min dp over [x, right-1]: a sprinkler starting at x can extend any of those prefixes.
		prefixBest := none
		for x := right - 1; x >= max(0, right-200); x-- {
			prefixBest = min(prefixBest, dp[x])
			baseByLeft[x] = prefixBest
		}
		best := none
		for i := max(0, right-100); i <= min(n, right+100); i++ {
			left, far := max(0, i-rs[i]), min(n, i+rs[i])
			if far < right || left >= right {
				continue
			}
			if base := baseByLeft[left]; base != none {
				best = min(best, base+cs[i])
			}
		}
		dp[right] = best
	}
	if dp[n] == none {
		fmt.Println(-1)
	} else {
		fmt.Println(dp[n])
	}
}
